    [4840]={name="Long Bayonet",quality=1,ilvl=10,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'Bounty on Murlocs'. Pick it over the other reward choices. Starts with Guard Thomas in Elwynn Forest. Objective: Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge.",zone="Elwynn Forest",questName="Bounty on Murlocs",lore="The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn. Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well."},
